class InsufficientFunds(Exception):
    """Raised when a withdrawal exceeds the balance."""

def withdraw(balance, amount):
    if amount <= 0:
        raise ValueError("amount must be positive")
    if amount > balance:
        raise InsufficientFunds(f"balance {balance}, wanted {amount}")
    return balance - amount

for text in ["30", "abc", "500"]:
    try:
        amount = int(text)
        new_balance = withdraw(100, amount)
    except ValueError as e:
        print("bad input:", e)
    except InsufficientFunds as e:
        print("declined:", e)
    else:
        print("ok, new balance", new_balance)
    finally:
        print("--")
# ok, new balance 70 / -- / bad input: invalid literal for int() with base 10: 'abc' / --
# declined: balance 100, wanted 500 / --

def countdown(n):
    while n > 0:
        yield n            # hand out n and pause here
        n -= 1

gen = countdown(3)
print(next(gen), next(gen))    # 3 2
print(list(gen))               # [1]  (only what's left)
print(list(gen))               # []   (exhausted)

def evens():
    n = 0
    while True:                # infinite, but lazy
        yield n
        n += 2

from itertools import islice
print(list(islice(evens(), 5)))     # [0, 2, 4, 6, 8]

def error_lines(lines):
    for line in lines:
        if "ERROR" in line:
            yield line.strip()

log = ["INFO start\n", "ERROR disk full\n", "INFO retry\n", "ERROR timeout\n"]
for line in error_lines(log):
    print(line)                # ERROR disk full / ERROR timeout

from dataclasses import dataclass, field

@dataclass
class Item:
    name: str
    price: float
    qty: int = 1

    def subtotal(self) -> float:
        return self.price * self.qty

@dataclass
class Cart:
    owner: str
    items: list[Item] = field(default_factory=list)   # not = []

    def total(self) -> float:
        return sum(i.subtotal() for i in self.items)

cart = Cart("Ana")
cart.items.append(Item("pen", 1.5, 4))
cart.items.append(Item("pad", 3.0))
print(cart.items[0])                          # Item(name='pen', price=1.5, qty=4)
print(cart.total())                           # 9.0
print(Item("pad", 3.0) == Item("pad", 3.0))   # True

